class TrayParentData extends ContainerBoxParentData<RenderBox> {
  double weight = 1;
}

class RenderTray extends RenderBox
    with ContainerRenderObjectMixin<RenderBox, TrayParentData> {
  @override
  void setupParentData(RenderBox child) {
    // Called when this parent adopts the child: the slot belongs to the parent
    if (child.parentData is! TrayParentData) child.parentData = TrayParentData();
  }

  @override
  void performLayout() {
    // ... reads (child.parentData! as TrayParentData).weight for each child
  }
}

class Weighted extends ParentDataWidget<TrayParentData> {
  const Weighted({super.key, required this.weight, required super.child});

  final double weight;

  @override
  void applyParentData(RenderObject renderObject) {
    final data = renderObject.parentData! as TrayParentData;
    if (data.weight == weight) return;       // unchanged: do not dirty anything
    data.weight = weight;
    renderObject.parent?.markNeedsLayout();  // the PARENT reads it, so it relayouts
  }

  @override
  Type get debugTypicalAncestorWidgetClass => Tray; // quoted in the error message
}

// ✅ the note lands on the render object RenderTray owns
Tray(children: [
  Weighted(weight: 2, child: Padding(padding: pad, child: const Text('a'))),
]);

// ❌ RenderPadding takes the slot; Weighted then writes into a BoxParentData
Tray(children: [
  Padding(padding: pad, child: const Weighted(weight: 2, child: Text('a'))),
]);

class RenderBadge extends RenderBox {
  RenderBadge({required Color color, required double radius})
      : _color = color,
        _radius = radius;

  Color _color;
  set color(Color value) {
    if (value == _color) return; // updateRenderObject re-assigns on every build
    _color = value;
    markNeedsPaint();            // ✅ pixels only — the layout is still valid
    // markNeedsLayout();        // ❌ re-runs performLayout for a colour change
  }

  double _radius;
  set radius(double value) {
    if (value == _radius) return;
    _radius = value;
    markNeedsLayout();           // ✅ geometry: our size changes, parents care
  }

  @override
  void performLayout() => size = constraints.constrain(Size.square(_radius * 2));

  @override
  void paint(PaintingContext context, Offset offset) {
    context.canvas.drawCircle(
      offset + size.center(Offset.zero),
      _radius,
      Paint()..color = _color,
    );
  }
}

class Badge extends LeafRenderObjectWidget {
  const Badge({super.key, required this.color, required this.radius});

  final Color color;
  final double radius;

  @override
  RenderBadge createRenderObject(BuildContext context) =>
      RenderBadge(color: color, radius: radius);

  @override
  void updateRenderObject(BuildContext context, RenderBadge renderObject) {
    renderObject
      ..color = color     // same values on most rebuilds — the guards absorb them
      ..radius = radius;
  }
}

class _ChartState extends State<Chart> {
  StreamSubscription<Tick>? _sub;
  Tick? _last;

  @override
  void initState() {
    super.initState();
    _sub = widget.feed.listen((tick) {
      // Between deactivate() and dispose() this is a silent no-op:
      // markNeedsBuild() returns early for an element that is not active.
      if (!mounted) return;
      setState(() => _last = tick);
    });
  }

  @override
  void deactivate() {
    // The widget has left the tree — but this is not the end: a GlobalKey
    // can reactivate this same element later in this very frame.
    super.deactivate();
  }

  @override
  void activate() {
    super.activate(); // reparented: didChangeDependencies re-runs, build follows
  }

  @override
  void dispose() {
    _sub?.cancel();   // ✅ the only hook guaranteed to be terminal
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Text('${_last?.value ?? '—'}');
}

// Order for a removed subtree, within one frame:
//   parent.deactivateChild(child)  -> detachRenderObject, into _inactiveElements
//   child.deactivate() (subtree)   -> State.deactivate
//   buildOwner.finalizeTree()      -> unmount the leftovers, deepest first
//   child.unmount()                -> State.dispose, element is defunct

class _PulseState extends State<Pulse> with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(
    vsync: this, // the mixin binds ticker.muted to TickerMode.getNotifier(context)
    duration: const Duration(seconds: 1),
  );

  @override
  void initState() {
    super.initState();
    // ❌ if an opaque route is pushed before this completes, the await hangs
    //    until the user pops back: the ticker is active but muted.
    _c.forward().then((_) => Navigator.of(context).pushNamed('/next'));
  }

  @override
  Widget build(BuildContext context) {
    debugPrint('ticking here? ${TickerMode.of(context)}'); // false under a route
    return FadeTransition(opacity: _c, child: const Logo());
  }

  @override
  void dispose() {
    _c.dispose(); // ✅ otherwise: "<state> was disposed with an active Ticker."
    super.dispose();
  }
}

// ✅ drive navigation from the state you control, not from a frame clock
//    that the Navigator itself can stop:
//    unawaited(_c.forward());
