// Hidden but still ticking every frame — TickerMode is the only mute switch:
//   Offstage(offstage: true, child: Pulse())
//   IndexedStack(index: 0, children: [Page(), Pulse()])
// Muted:
//   Visibility(visible: false, maintainState: true, maintainAnimation: false,
//              child: Pulse())

class _ParentState extends State<Parent> {
  int _n = 0;

  void bump() => setState(() => _n++); // marks dirty + schedules a frame

  @override
  Widget build(BuildContext context) {
    debugPrint('parent build');
    return Child(value: _n); // deeper: sorted after the parent
  }
}

class _ChildState extends State<Child> {
  @override
  Widget build(BuildContext context) {
    debugPrint('child build'); // prints ONCE even though both setStates ran
    return Text('${widget.value}');
  }
}

// Same turn of the event loop -> one frame, one build per element:
//   parentState.bump();
//   childState.setState(() {});
// dirty list [Parent(depth 12), Child(depth 13)] sorted by depth:
//   Parent.rebuild() -> updateChild -> Child.update() -> rebuild(force: true)
//   Child's own entry reached -> _dirty already false -> skipped

class _Row extends State<Row2> {
  @override
  Widget build(BuildContext context) {
    // ❌ dirties an ancestor mid-build: the walk cannot go back up
    context.findAncestorStateOfType<_ParentState>()!.bump();
    // "setState() or markNeedsBuild() called during build."

    // ✅ defer it out of the build phase
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) context.findAncestorStateOfType<_ParentState>()?.bump();
    });
    return const SizedBox();
  }
}

