class RenderStackedPair extends RenderBox
    with
        ContainerRenderObjectMixin<RenderBox, BoxParentData>,
        RenderBoxContainerDefaultsMixin<RenderBox, BoxParentData> {
  // One sizing rule, two callers: the dry pass measures, the wet pass lays out.
  Size _computeSize(BoxConstraints constraints, ChildLayouter layoutChild) {
    double width = 0;
    double height = 0;
    for (RenderBox? child = firstChild; child != null; child = childAfter(child)) {
      final childSize = layoutChild(child, constraints.loosen());
      width = math.max(width, childSize.width);
      height += childSize.height;
    }
    return constraints.constrain(Size(width, height));
  }

  @override
  Size computeDryLayout(BoxConstraints constraints) =>
      _computeSize(constraints, ChildLayoutHelper.dryLayoutChild); // pure

  @override
  void performLayout() {
    size = _computeSize(constraints, ChildLayoutHelper.layoutChild); // same rule
    double dy = 0;
    for (RenderBox? child = firstChild; child != null; child = childAfter(child)) {
      (child.parentData! as BoxParentData).offset = Offset(0, dy);
      dy += child.size.height;
    }
  }

  @override
  double? computeDryBaseline(BoxConstraints constraints, TextBaseline baseline) =>
      firstChild?.getDryBaseline(constraints.loosen(), baseline);

  // When the size comes from a callback and cannot be answered honestly:
  //   assert(debugCannotComputeDryLayout(reason: 'size comes from a callback'));
  //   return Size.zero;
}

